var Connection = New COMObject("ADODB.Connection");
Connection.Open(ConnectionString);
var Records = Connection.Execute("SELECT Name FROM Goods");
while (Not Records.EOF) {
    Message(Records.Fields("Name").Value);
    Records.MoveNext();
}
Connection.Close();

